CREATE TABLE IF NOT EXISTS connector_contract_profiles(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,family_key TEXT NOT NULL,provider_key TEXT NOT NULL,contract_version TEXT NOT NULL,official_sources_json TEXT NOT NULL,request_contract_json TEXT NOT NULL,webhook_contract_json TEXT NOT NULL,verified INTEGER NOT NULL CHECK(verified IN(0,1)),verified_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,family_key,provider_key));
CREATE INDEX IF NOT EXISTS connector_contract_profile_scope_idx ON connector_contract_profiles(organization_id,property_id,family_key,verified);
